function hpeVolumeNormalize(value){return String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('pt-BR')}
function hpeCanonicalVolumeGroup(value){const s=hpeVolumeNormalize(value);if(/peitoral|peito|chest/.test(s))return 'Peitoral';if(/costas|dorsal|latissimo|trapezio|romboide|back/.test(s))return 'Costas';if(/ombro|deltoide|shoulder/.test(s))return 'Ombros';if(/biceps|bicep/.test(s))return 'Bíceps';if(/triceps|tricep/.test(s))return 'Tríceps';if(/quadriceps|quadricep/.test(s))return 'Quadríceps';if(/isquiotibial|posterior de coxa|hamstring|femoral/.test(s))return 'Posterior de coxa';if(/glute/.test(s))return 'Glúteos';if(/panturrilha|gastrocnemio|soleo|calf/.test(s))return 'Panturrilhas';if(/abdomen|abdominal|obliquo|core/.test(s))return 'Abdômen';if(/antebraco|forearm|punho/.test(s))return 'Antebraços';if(/adutor|abdutor|adductor|abductor/.test(s))return 'Adutores/abdutores';return ''}
function hpeVolumeGroups(exercise){const explicit=hpeCanonicalVolumeGroup(`${exercise.muscle||''} ${muscleLibrary[exercise.muscle]?.label||''}`);if(explicit)return [explicit];const key=window.hpeExerciseNameKey||hpeVolumeNormalize,name=key(exercise.name);for(const [muscle,group] of Object.entries(muscleLibrary)){if((group.exercises||[]).some(item=>key(item)===name)){const matched=hpeCanonicalVolumeGroup(`${muscle} ${group.label}`);if(matched)return [matched]}}const text=hpeVolumeNormalize(`${exercise.name||''} ${exercise.notes||''}`),hits=[];const add=(group,pattern)=>{if(pattern.test(text)&&!hits.includes(group))hits.push(group)};add('Peitoral',/peitoral|peito|supino|crucifixo|crossover|pec deck|voador|flexao de braco/);add('Costas',/costas|dorsal|remada|puxada|barra fixa|latissimo|pullover|pull over|trapezio|romboide/);add('Ombros',/ombro|deltoide|desenvolvimento|elevacao lateral|elevacao frontal|face pull|crucifixo inverso/);add('Bíceps',/biceps|rosca direta|rosca alternada|rosca martelo|rosca scott/);add('Tríceps',/triceps|tricep testa|triceps testa|triceps corda|triceps na polia|frances/);add('Quadríceps',/quadriceps|agachamento|leg press|extensora|hack/);add('Posterior de coxa',/posterior de coxa|isquiotibial|stiff|terra romeno|cadeira flexora|mesa flexora|hamstring/);add('Glúteos',/glute|hip thrust|elevacao pelvica|coice|kickback/);add('Panturrilhas',/panturrilha|gastrocnemio|soleo|calf/);add('Abdômen',/abdomen|abdominal|obliquo|prancha|core/);add('Antebraços',/antebraco|rosca de punho|punho inversa|wrist/);add('Adutores/abdutores',/adutor|abdutor|abducao|aducao/);return hits.length?hits:['A classificar']}
function hpeSetVolumePanel(id){const blocks=[data.plans?.[id],...Object.values(data.alternatePlans?.[id]||{})].filter(Array.isArray),totals=new Map();for(const block of blocks)for(const exercise of block){const sets=Math.max(0,Math.floor(Number(exercise.sets)||0));if(!sets)continue;for(const group of hpeVolumeGroups(exercise))totals.set(group,(totals.get(group)||0)+sets)}const rows=[...totals].sort((a,b)=>a[0]==='A classificar'?1:b[0]==='A classificar'?-1:a[0].localeCompare(b[0],'pt-BR'));return `<section class="card set-volume-panel"><div class="row"><div><span class="eyebrow">DOSE DE TREINO · VISÃO SEMANAL</span><h2>Volume por grupo muscular</h2></div><span class="tag">${[...totals.values()].reduce((sum,n)=>sum+n,0)} séries</span></div><p>Estimativa ao vivo, somando uma vez cada divisão ativa do aluno.</p>${rows.length?`<div class="set-volume-list">${rows.map(([group,sets])=>{const status=group==='A classificar'?'Revise o grupo':sets<10?'Abaixo da faixa':sets<=20?'Ideal · faixa de referência':'Acima da faixa';return `<div class="set-volume-row"><div class="row"><b>${esc(group)}</b><strong>${sets} séries/semana</strong></div><div class="set-volume-track"><span style="width:${Math.min(100,sets/20*100)}%"></span></div><small class="set-volume-status ${sets>=10&&sets<=20?'in-range':sets>20?'high-volume':''}">${status}</small></div>`}).join('')}</div>`:'<div class="empty">Adicione exercícios para acompanhar o volume semanal.</div>'}<p class="note">Faixa geral de referência: 10–20 séries por grupo na semana. É uma estimativa pelo músculo principal; exercícios compostos também estimulam músculos secundários. Ajuste ao aluno, recuperação e objetivo.</p></section>`}
let trainingTab='mapa';
window.setTrainingTab=tab=>{if(!['mapa','exercicios','lista'].includes(tab))return;trainingTab=tab;render()};
const tabChooseMuscle=window.chooseMuscle;window.chooseMuscle=key=>{if(!muscleLibrary[key]||role!=='personal')return;trainingTab='exercicios';tabChooseMuscle(key)};
window.filterExerciseNames=value=>{const query=value.toLocaleLowerCase('pt-BR').normalize('NFD').replace(/[\u0300-\u036f]/g,'');let visible=0;document.querySelectorAll('.pane-exercicios #muscle-exercises .exercise').forEach(row=>{const text=row.textContent.toLocaleLowerCase('pt-BR').normalize('NFD').replace(/[\u0300-\u036f]/g,'');row.hidden=!text.includes(query);if(!row.hidden)visible++});const message=$('#exercise-search-result');if(message)message.textContent=visible?`${visible} exercícios encontrados`:'Nenhum exercício encontrado. Tente outro nome.'};
const editFromTabs=window.editExercise;window.editExercise=(index,preset)=>{editFromTabs(index,preset);if(role!=='personal')return;const form=$('#exerciseForm'),submit=form.onsubmit;form.onsubmit=event=>{const prior=JSON.stringify(plan());submit(event);if(JSON.stringify(plan())!==prior){trainingTab='lista';render();toast('Exercício salvo na lista de treino do aluno.')}}};
const renderTrainingTabs=render;render=function(){renderTrainingTabs();if(role!=='personal'||page!=='treinos')return;const container=$('#content');const planHtml=container.lastElementChild.outerHTML.replace('onclick="editExercise()"','onclick="setTrainingTab(\'exercicios\')"');const labels=[['mapa','Mapa muscular'],['exercicios','Exercícios'],['lista','Treino do aluno']];container.innerHTML=heading('PLANO PERSONALIZADO',`Treino de ${esc(current().name.split(' ')[0])}.`,'Escolha o músculo, selecione os exercícios e organize o plano.',studentSelector())+`<div class="training-tabs" role="tablist" aria-label="Etapas da criação de treino">${labels.map(([key,label])=>`<button id="training-tab-${key}" role="tab" aria-controls="training-pane" aria-selected="${trainingTab===key}" class="${trainingTab===key?'primary':''}" onclick="setTrainingTab('${key}')">${label}${key==='lista'?` <span class="tab-count">${plan().length}</span>`:''}</button>`).join('')}</div><section id="training-pane" class="pane-${trainingTab}" role="tabpanel" aria-labelledby="training-tab-${trainingTab}">${trainingTab==='lista'?planHtml:musclePicker()}</section>`;if(trainingTab==='lista')$('.pane-lista').insertAdjacentHTML('beforeend',hpeSetVolumePanel(student));if(trainingTab==='exercicios'){$('#muscle-exercises').insertAdjacentHTML('afterbegin',`<div class="exercise-search"><label>Buscar exercício<input type="search" placeholder="Ex.: supino inclinado" aria-label="Buscar exercício" oninput="filterExerciseNames(this.value)"></label><p id="exercise-search-result" role="status"></p></div>`)}else if(trainingTab==='mapa'){$('.body-panel').insertAdjacentHTML('beforeend',`<div class="anatomy-key"><span class="key-normal"></span> Grupo muscular <span class="key-selected"></span> Selecionado</div>`);$('.muscle-options').insertAdjacentHTML('beforeend',`<div class="selected-muscle-info"><span class="eyebrow">GRUPO SELECIONADO</span><h2>${esc(muscleLibrary[selectedMuscle].label)}</h2><p>${muscleLibrary[selectedMuscle].exercises.length} exercícios disponíveis. Toque no corpo ou escolha um grupo acima.</p><button class="primary" onclick="setTrainingTab('exercicios')">Ver exercícios ↗</button></div>`)}};

